122	  /**
123	   * Transforms a raw filesystem directory name into a valid SLUG_REGEX slug.
124	   * Rules applied in order:
125	   *   1. Lowercase
126	   *   2. Replace any character that is not [a-z0-9_-] with a hyphen
127	   *   3. Strip any leading characters that are not alphanumeric
128	   *   4. Collapse consecutive hyphens into a single hyphen
129	   *   5. Fall back to 'repo' if the result is empty
130	   */
131	  function sanitiseSlug(raw) {
132	    var slug = raw
133	      .toLowerCase()
134	      .replace(/[^a-z0-9_-]/g, '-')
135	      .replace(/^[^a-z0-9]+/, '')
136	      .replace(/-{2,}/g, '-');
137	    return slug || 'repo';
138	  }
